<script setup>
import { computed, nextTick, ref, watch } from 'vue'
import { objectRequest } from '../../data-object-api.js'
import DirectoryTree from '../../DirectoryTree.vue'
import { dictionaryField } from './dictionary-field.js'
const props=defineProps({modelValue:Boolean,sourceType:String,existing:Array})
const emit=defineEmits(['update:modelValue','select'])
const dirs=ref([]),rows=ref([]),total=ref(0),page=ref(1),size=ref(10),directory=ref(0),search=ref(''),query=ref(''),selected=ref(new Map()),table=ref(null),error=ref(''),loading=ref(false),syncing=ref(false)
const names=computed(()=>new Set((props.existing||[]).map(f=>String(f.name||'').toLowerCase()).filter(Boolean)))
function eligibility(row){if(names.value.has(row.code.toLowerCase()))return '字段已存在';const limit=props.sourceType==='ORACLE'?30:props.sourceType==='POSTGRESQL'?63:64;if(row.code.length>limit)return `标识超过目标数据库 ${limit} 字符限制`;if(/[\\\x00-\x1f]/.test(row.meaning||row.name||''))return '字段注释含不支持的字符';return dictionaryField(row,props.sourceType).error||''}
let seq=0
async function load(){const current=++seq;try{loading.value=true;error.value='';const q=new URLSearchParams({page:String(page.value),size:String(size.value),search:query.value});if(directory.value)q.set('directoryId',String(directory.value));const result=await objectRequest(`/api/dictionary/entries?${q}`);if(current!==seq)return;rows.value=result.rows;total.value=result.total;syncing.value=true;await nextTick();for(const row of rows.value)if(selected.value.has(row.id))table.value?.toggleRowSelection(row,true);await nextTick();syncing.value=false}catch(e){if(current===seq)error.value=e.message}finally{if(current===seq)loading.value=false}}
watch(()=>props.modelValue,async open=>{if(!open)return;dirs.value=[];rows.value=[];selected.value=new Map();directory.value=0;search.value='';query.value='';page.value=1;error.value='';try{dirs.value=await objectRequest('/api/dictionary/directories');await load()}catch(e){error.value=e.message}})
function changed(selection){if(syncing.value)return;const next=new Map(selected.value);for(const row of rows.value)next.delete(row.id);for(const row of selection)if(!eligibility(row))next.set(row.id,row);selected.value=next}
function applyQuery(){query.value=search.value.trim();page.value=1;load()}
function choose(){const entries=[...selected.value.values()];const result=entries.map(e=>dictionaryField(e,props.sourceType));const usable=result.filter(r=>r.field);emit('select',{fields:usable.map(r=>r.field),missingLength:usable.filter(r=>r.needsLength).map(r=>r.field.name)});emit('update:modelValue',false)}
</script>
<template><el-dialog :model-value="modelValue" title="从数据字典选择字段" width="min(1000px,96vw)" append-to-body @update:model-value="emit('update:modelValue',$event)"><el-alert v-if="error" :title="error" type="error" show-icon/><div class="picker"><DirectoryTree :directories="dirs" root-label="字典目录" :selected="directory" readonly @select="directory=$event;page=1;load()"/><main><div class="picker-query"><el-input v-model="search" placeholder="搜索字典标识、名称或含义" clearable @keyup.enter="applyQuery"/><el-button type="primary" @click="applyQuery">查询</el-button></div><el-table ref="table" v-loading="loading" :data="rows" row-key="id" max-height="350" @selection-change="changed"><el-table-column type="selection" width="48" :selectable="row=>!eligibility(row)"/><el-table-column prop="code" label="字典标识" min-width="120"/><el-table-column prop="name" label="字典名" min-width="120"/><el-table-column prop="meaning" label="字典含义" min-width="140"/><el-table-column prop="dataType" label="类型" width="100"/><el-table-column prop="length" label="长度" width="70"/><el-table-column prop="precision" label="精度" width="70"/><el-table-column label="说明" min-width="160"><template #default="s">{{eligibility(s.row) || (dictionaryField(s.row,sourceType).needsLength?'需补填长度':'可选择')}}</template></el-table-column></el-table><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @current-change="load" @size-change="page=1;load()"/></main></div><template #footer><span class="count">已选择 {{selected.size}} 个字段</span><el-button @click="emit('update:modelValue',false)">取消</el-button><el-button type="primary" :disabled="!selected.size" @click="choose">确定</el-button></template></el-dialog></template>
<style scoped>.picker{display:flex;gap:14px;min-height:360px}.picker main{min-width:0;flex:1}.picker-query{display:flex;align-items:center;gap:10px;margin-bottom:12px}.picker-query :deep(.el-input){flex:0 1 300px;width:300px;min-width:0}.picker-query :deep(.el-button){flex:none;height:32px;min-height:32px;padding:0 15px}.el-pagination{justify-content:flex-end;margin-top:12px}.count{margin-right:14px;color:#606f80}@media(max-width:700px){.picker{flex-direction:column}.picker-query :deep(.el-input){flex:1 1 0;width:auto}.el-pagination{flex-wrap:wrap;row-gap:8px}}</style>
